/**
 * Registra o logotipo no sprite (impresso uma vez no rodapé).
 */
function ep_logo_used( bool $set = false ): bool {
	static $used = false;
	if ( $set ) {
		$used = true;
	}
	return $used;
}

/**
 * Imprime o logo como link para a página inicial.
 *
 * @param string $context header|footer (só muda a classe).
 */
function ep_logo( string $context = 'header' ): void {
	ep_logo_used( true );
	?>
	<a class="logo logo-<?php echo esc_attr( $context ); ?>" href="<?php echo esc_url( home_url( '/' ) ); ?>" rel="home" aria-label="<?php esc_attr_e( 'Eletroproj — início', 'eletroproj' ); ?>">
		<span class="logo-mark"><?php ep_icon( 'zap', 17, array( 'stroke' => 2.5 ) ); ?></span>
		<svg class="logo-wordmark" width="105" height="21" aria-hidden="true" focusable="false" fill="currentColor"><use href="#logo-wordmark"/></svg>
	</a>
	<?php
}
